//
// Tests for the meal-management write surface's payload-level mutation
// error detection. This is a hand-authored file (no "Generated by ..."
// header) so `generate --force` preserves it, matching forkable_orders.go.

package cli

import (
	"encoding/json"
	"strings"
	"testing"
)

// TestPayloadMutationErrors covers the payload shapes Forkable's mutations
// can return. Every mutation built in forkable_orders.go requests "errors"
// in its selection set, so mutateGraphQL must treat a non-null, non-empty
// "errors" array under the single operation key as a rejected mutation —
// regardless of whether array elements are strings or objects, and
// regardless of which operation name wraps them.
func TestPayloadMutationErrors(t *testing.T) {
	tests := []struct {
		name    string
		data    string
		wantErr bool
		wantSub string // substring expected in the error message, if wantErr
	}{
		{
			name:    "errors null means success",
			data:    `{"replacePiece": {"delivery": {"id": 1}, "errors": null}}`,
			wantErr: false,
		},
		{
			name:    "errors empty array means success",
			data:    `{"replacePiece": {"delivery": {"id": 1}, "errors": []}}`,
			wantErr: false,
		},
		{
			name:    "errors field absent means success",
			data:    `{"removeDelivery": {"errors": null}}`,
			wantErr: false,
		},
		{
			name:    "string error array is a failure",
			data:    `{"replacePiece": {"delivery": null, "errors": ["item requires a modifier selection"]}}`,
			wantErr: true,
			wantSub: "item requires a modifier selection",
		},
		{
			name:    "object error array is a failure",
			data:    `{"confirmDelivery": {"delivery": null, "errors": [{"field": "deliveryId", "message": "already confirmed"}]}}`,
			wantErr: true,
			wantSub: "already confirmed",
		},
		{
			name:    "multiple string errors are a failure",
			data:    `{"replaceAllPieces": {"deliveries": null, "errors": ["one", "two"]}}`,
			wantErr: true,
			wantSub: "one",
		},
		{
			name:    "non-object data does not panic",
			data:    `null`,
			wantErr: false,
		},
		{
			name:    "empty object data does not panic",
			data:    `{}`,
			wantErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := payloadMutationErrors(json.RawMessage(tt.data))
			if tt.wantErr && err == nil {
				t.Fatalf("payloadMutationErrors(%s) = nil, want error", tt.data)
			}
			if !tt.wantErr && err != nil {
				t.Fatalf("payloadMutationErrors(%s) = %v, want nil", tt.data, err)
			}
			if tt.wantErr && tt.wantSub != "" && !strings.Contains(err.Error(), tt.wantSub) {
				t.Fatalf("payloadMutationErrors(%s) error = %q, want substring %q", tt.data, err.Error(), tt.wantSub)
			}
		})
	}
}
